561	```ts
562	import { createHash } from 'node:crypto';
563	export const liveCheckTool = createTool({
564	  id: 'liveCheck', description: 'Search the web for closures/events at a named place this week (cached 12 h)',
565	  inputSchema: z.object({ query: z.string().max(120) }),
566	  execute: async ({ query }) => {
567	    const col = (await db()).collection<{ _id: string; results: unknown[] }>('serp_cache');
568	    const _id = createHash('sha1').update(query.toLowerCase()).digest('hex');
569	    const hit = await col.findOne({ _id }); if (hit) return { cached: true, results: hit.results };
570	    const u = new URL('https://serpapi.com/search.json');
571	    u.search = new URLSearchParams({ engine: 'google', q: query, num: '5', api_key: process.env.SERPAPI_KEY! }).toString();
572	    const j = await (await fetch(u, { signal: AbortSignal.timeout(15_000) })).json();
573	    const results = (j.organic_results ?? []).slice(0, 5).map((o: any) => ({ title: o.title, snippet: o.snippet, date: o.date }));
574	    await col.updateOne({ _id }, { $set: { query, results, fetchedAt: new Date() } }, { upsert: true });
575	    return { cached: false, results };
576	  },
577	});
578	```
