601	```ts
602	function tally(votes: Map<string, number[]>, n: number) {
603	  const counts = Array<number>(n).fill(0);
604	  for (const ids of votes.values()) for (const i of ids) if (i < n) counts[i]++;  // index n = "can't make it"
605	  const index = counts.indexOf(Math.max(...counts));
606	  return { index, count: counts[index], counts };
607	}
608	export async function planOuting(p: PlanInput): Promise<string> {
609	  let phase = 'drafting'; const votes = new Map<string, number[]>(); const recaps: wf.SignalArgs<any>[] = [];
610	  wf.setHandler(phaseQuery, () => phase);
611	  wf.setHandler(vote, (v) => void votes.set(v.userId, v.optionIds));
612	  wf.setHandler(recap, (r) => void recaps.push(r));
613	  const options: Option[] = await remote.draftPlans(p);                  // Render + Gemma
614	  await chat.sendPoll(p.planId, p.chatId, options);
615	  phase = 'voting';
616	  const reached = await wf.condition(() => tally(votes, options.length).count >= p.quorum, until(p.pollCloseAt));
617	  await chat.closePoll(p.planId);
618	  const t = tally(votes, options.length);
619	  if (!reached) { phase = 'no-quorum'; await chat.announce(p, 'no-quorum', { count: t.count }); return phase; }
620	```
