643	```ts
644	import { Context, ApplicationFailure } from '@temporalio/activity';
645	import { db, roster } from '../shared/db';
646	import type { PlanInput } from './workflows'; import type { Option } from '../shared/schema';
647	const HOME = { lat: Number(process.env.HOME_LAT), lon: Number(process.env.HOME_LON) };
648	async function logEvent(planId: string, type: string, detail: string) {
649	  await (await db()).collection('plans').updateOne({ _id: planId as any },
650	    { $push: { events: { at: new Date(), type, detail } } as any }, { upsert: true });
651	}
652	async function render(planId: string, path: string, body: unknown) {
653	  const { attempt, activityType } = Context.current().info; const t0 = Date.now();
654	  try {
655	    const r = await fetch(`${process.env.RENDER_URL}${path}`, { method: 'POST', body: JSON.stringify(body),
656	      headers: { 'content-type': 'application/json', 'x-quorum-secret': process.env.QUORUM_SHARED_SECRET! },
657	      signal: AbortSignal.timeout(25_000) });                             // fail fast; Temporal retries
658	    if (r.status === 400 || r.status === 401)
659	      throw ApplicationFailure.create({ type: 'BadRequest', message: await r.text(), nonRetryable: true });
660	    if (!r.ok) throw new Error(`render ${r.status}`);                    // 5xx while waking, 429 from Gemma
661	    await logEvent(planId, activityType, `attempt ${attempt} ok in ${Date.now() - t0} ms`);
662	    return await r.json();
663	  } catch (e: any) { await logEvent(planId, activityType, `attempt ${attempt} failed: ${e.name}: ${e.message}`); throw e; }
664	}
